 GenerationJdbcStoreTest f;JdbcReportSupplementActions actions;JdbcReportSupplementActions.Command command;JdbcReportSupplementActions.Accepted value;
 String key=JdbcReportSupplementActions.action("fictional-client-key");Instant now=Instant.parse("2026-01-02T01:00:00.123456Z");
 GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
 @BeforeEach void setup(){f=fixture();f.fixture();if(f.source instanceof org.h2.jdbcx.JdbcDataSource local)local.setURL(local.getURL()+";INIT=SET TIME ZONE 'UTC'");f.jdbc.execute("ALTER TABLE jobs ADD COLUMN result_hash BINARY(32)");actions=new JdbcReportSupplementActions(f.source);var scope=new JdbcLatestReportIntent.Scope("report:daily:2026-01-01","daily_report",LocalDate.parse("2026-01-01"));command=new JdbcReportSupplementActions.Command(scope,0,null,null,"fictional-owner","Fictional explicit source supplement");value=new JdbcReportSupplementActions.Accepted(JdbcReportSupplementActions.operation(key),JdbcReportPreparedInputs.root(scope.logicalKey(),2),JdbcFrozenInputs.stableId("intent",scope.logicalKey()+":2"),2,1,JdbcFrozenInputs.stableId("report-content",scope.logicalKey()),null,now,"a".repeat(64),"b".repeat(64),"queued","c".repeat(64),"free",0,null);}
 <T>T rr(java.util.function.Supplier<T> run){var tx=new TransactionTemplate(new DataSourceTransactionManager(f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->run.get());}
 JdbcReportSupplementActions.Accepted save(){return f.writes.execute(new SharedWriteExecutor.ActionContext(key,value.operationId(),null),k->actions.read(k,command),a->{actions.append(key,command,value,now);return actions.read(key,command);});}
 @Test void NativePermanentExactReceiptSurvivesRestartAndNeverCreatesReportRoots(){assertNull(rr(()->actions.read(key,command)));assertEquals(value,save());assertEquals(value,save());actions=new JdbcReportSupplementActions(f.source);assertEquals(value,rr(()->actions.read(key,command)));assertEquals(1L,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));assertEquals(0L,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='logical_task'",Long.class));assertTrue(value.toString().contains("redacted"));assertTrue(command.toString().contains("redacted"));}
 @Test void SameKeyWrongCommandIsConflictOnlyAfterWholeNativeReceiptValidation(){save();var other=new JdbcReportSupplementActions.Command(command.scope(),1,null,null,command.actor(),command.reason());assertThrows(JdbcReportSupplementActions.Conflict.class,()->rr(()->actions.read(key,other)));f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE id=?",new byte[32],value.operationId());var error=assertThrows(RuntimeException.class,()->rr(()->actions.read(key,other)));assertFalse(error instanceof JdbcReportSupplementActions.Conflict);}
 @Test void DamagedNativeIdentityBudgetRoleTimestampOrPayloadCannotReplay(){save();f.jdbc.update("UPDATE jobs SET target_id='fictional-other' WHERE id=?",value.operationId());assertThrows(RuntimeException.class,()->rr(()->actions.read(key,command)));setup();save();f.jdbc.update("UPDATE jobs SET owner_job_id='fictional-borrowed-root' WHERE id=?",value.operationId());assertThrows(RuntimeException.class,()->rr(()->actions.read(key,command)));setup();save();f.jdbc.update("UPDATE jobs SET reason='Fictional altered command' WHERE id=?",value.operationId());assertThrows(RuntimeException.class,()->rr(()->actions.read(key,command)));setup();save();f.jdbc.update("UPDATE jobs SET revision=1 WHERE id=?",value.operationId());assertThrows(RuntimeException.class,()->rr(()->actions.read(key,command)));}
 @Test void NativeReceiptFailureRollsBackAndMalformedCommandsTransactionsOrScopeRefuse(){f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_supplement_receipt_failure CHECK(target_type IS NULL OR target_type<>'report_supplement_request')");assertThrows(RuntimeException.class,this::save);assertEquals(0L,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));assertThrows(RuntimeException.class,()->actions.read(key,command));assertThrows(RuntimeException.class,()->rr(()->{actions.append(key,command,value,now);return true;}));assertThrows(RuntimeException.class,()->JdbcReportSupplementActions.action("bad key"));assertThrows(RuntimeException.class,()->new JdbcReportSupplementActions.Command(command.scope(),0,"fictional-content",null,"fictional-owner","Fictional invalid"));var source=mock(javax.sql.DataSource.class);new JdbcReportSupplementActions(source);verifyNoInteractions(source);}
 @Test void ConcurrentIdenticalKeysCommitOneNativeReceiptWithOriginalAcceptedResult()throws Exception{try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=pool.submit(this::save);var two=pool.submit(this::save);assertEquals(value,one.get(10,java.util.concurrent.TimeUnit.SECONDS));assertEquals(value,two.get(10,java.util.concurrent.TimeUnit.SECONDS));}assertEquals(1L,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));}
 @Test void WholeSecondCutoffRetainsSixDigitWirePrecisionAndNativeUtcIdentity(){now=Instant.parse("2026-01-02T01:00:00Z");value=new JdbcReportSupplementActions.Accepted(value.operationId(),value.rootId(),value.intentId(),value.generation(),value.intentRevision(),value.contentId(),value.baseRevision(),now,value.inputHash(),value.businessInputHash(),value.state(),value.originalReceiptHash(),value.slotState(),value.slotRevision(),value.occupiedAttemptId());assertEquals(value,save());assertEquals(now,rr(()->actions.read(key,command)).cutoff());}

 @Test void OriginalCommandAndSlotObservationArePermanentRatherThanLaterNativeState(){save();var original=rr(()->actions.original(key));assertEquals(command,original.command());assertEquals(value,original.accepted());assertEquals("free",original.accepted().slotState());assertEquals(0,original.accepted().slotRevision());assertNull(original.accepted().occupiedAttemptId());assertTrue(original.toString().contains("redacted"));}

